    public static async Task Run(Action<bool, string> check, string root, RulesetParams ruleset)
    {
        var api = new ApiClient(new FakeServer(), new Tokens(), new ApiClientOptions { BaseUrl = "http://fake", Retry = new RetryPolicy { MaxRetries = 0 } });
        var b = new GameBackend(new GameSettings { BaseUrl = "http://fake" }, api, null, new MemoryKeyValueStore(), ruleset);
        var prevRule = GameDay.Rule;
        GameDay.Use(new DayRolloverInfo { HourJst = 4, PreviousHourJst = 0, EffectiveAtMs = 1796065200000 });
        try
        {
            var v3 = GoalLadderView.FromJson(Day3);
            var m3 = new GoalLadderModel(b, () => v3.Now);
            m3.Use(v3);
            var path3 = m3.Rungs.FirstOrDefault(r => r.Key == "path");
            check(path3 != null && path3.Main == "フレンドを追加" && path3.Sub == "ひとりでも：相棒におやつをあげる", "week 2: the friend step names its solo way, gently (" + path3?.Main + " / " + path3?.Sub + ")");
            check(m3.PathScreen == "friends" && m3.PathAltScreen == "training" && m3.PathAltLine == "ひとりでも：相棒におやつをあげる", "week 2: the solo way opens the training screen (" + m3.PathAltScreen + ")");
            check(m3.Rungs.All(r => r.Key != "week2") && m3.Week2Days.Count == 0 && m3.Week2Goal == null, "week 2: no arc before day 7");

            var v7 = GoalLadderView.FromJson(Day7);
            var m7 = new GoalLadderModel(b, () => v7.Now);
            m7.Use(v7);
            check(m7.TomorrowLine == "明日：はじめの10歩 卒業（10連スカウト券×1）" && m7.TomorrowLines.Contains("ログインボーナス：無償コイン50枚"), "week 2: day 7's home line is graduation, not the 50 coins (the sheet keeps both) (" + m7.TomorrowLine + ")");
            check(m7.TomorrowLines.Count > 0 && m7.TomorrowLines[0] == "はじめの10歩を卒業：10連スカウト券×1", "week 2: the sheet's first tomorrow line (" + (m7.TomorrowLines.Count > 0 ? m7.TomorrowLines[0] : "none") + ")");
            check(m7.PathWaitText == "明日 受け取れます", "week 2: graduation waits for its day (" + m7.PathWaitText + ")");
            var arc7 = m7.Rungs.FirstOrDefault(r => r.Key == "week2");
            check(arc7 != null && m7.Rungs.All(r => r.Key != "path") && m7.Rungs.Count <= 4, "week 2: the arc takes the path's place (at most four rungs: " + string.Join(",", m7.Rungs.Select(r => r.Key)) + ")");
            check(arc7.Label == "2週目" && arc7.Main == "14日目 SR以上確定券" && arc7.Sub == "明日から2週目" && arc7.Figure == null && m7.Week2Goal == "14日目：SR以上確定スカウト券×1", "week 2: the preview names the week's peak (graduation is today's 明日 line) (" + arc7.Main + " / " + arc7.Sub + ")");
            check(m7.Week2Days.Count == 7 && m7.Week2Days[0].DayLabel == "8日目" && m7.Week2Days[0].GraduateText == "はじめの10歩 卒業：10連スカウト券×1" && m7.Week2Days.All(x => x.RewardText != null), "week 2: one reason a day, every day 8..14");
            check(m7.Week2Days[6].Peak && m7.Week2Days[6].RewardText == "SR以上確定スカウト券×1" && m7.Week2Days[6].ShortText == "SR以上" && m7.Week2Days[1].ShortText == "素材×3" && m7.Week2Days.Count(x => x.Peak) == 1, "week 2: day 14's guaranteed-SR ticket is the peak (" + m7.Week2Days[6].RewardText + ")");
            check(m7.Partner != null && m7.Partner.TreatLine == "りんごのおやつで伸び 85% → 100%", "week 2: the partner plate says what a treat does (" + m7.Partner?.TreatLine + ")");

            var v10 = GoalLadderView.FromJson(Day10);
            var m10 = new GoalLadderModel(b, () => v10.Now);
            m10.Use(v10);
            var arc10 = m10.Rungs.FirstOrDefault(r => r.Key == "week2");
            check(arc10 != null && arc10.Figure == "3/7" && arc10.Ready && arc10.Main == "受け取れる報酬があります" && arc10.Sub == "明日：無償コイン100枚", "week 2: day 10 — 3/7, graduation ready to claim, tomorrow's reason (" + arc10?.Figure + " / " + arc10?.Main + " / " + arc10?.Sub + ")");
            check(m10.Week2Days.Count(x => x.Past) == 2 && m10.Week2Days.Single(x => x.Today).PlayerDay == 10, "week 2: past days and today marked");
            check(m10.Partner.TreatLine == null, "week 2: no treat line when the partner is fresh");
            check(GoalLadderModel.TreatText(new TreatHint { Name = "りんごのおやつ", Tired = true, Unblocks = true, EfficiencyPermille = 500, EfficiencyAfterPermille = 750 }) == "りんごのおやつで疲れをとると、今日も調教できます", "week 2: a tired horse — the treat lets it train today");

            // an older server (no week-2 fields): nothing invented
            var old = new GoalLadderModel(b, () => v3.Now);
            old.Use(GoalLadderView.FromJson(Day3.Replace(",\"alt\":{\"kind\":\"treat\",\"target\":1,\"progress\":0,\"screen\":\"training\",\"open\":true}", "")));
            check(old.PathAltLine == null && old.Rungs.First(r => r.Key == "path").Sub.StartsWith("最後に "), "week 2: without alt the path rung keeps its final reward line");

            var all = new List<string> { path3.Main, path3.Sub, m7.TomorrowLine, arc7.Main, arc7.Sub, arc10.Main, arc10.Sub, m7.PathWaitText, m7.Partner.TreatLine, "8日目から受け取れます", "りんごのおやつで疲れをとると、今日も調教できます" };
            all.AddRange(m7.TomorrowLines);
            all.AddRange(m7.Week2Days.SelectMany(x => new[] { x.DayLabel, x.RewardText, x.GraduateText, x.ShortText }));
            all.Add(m7.Week2Goal);
            all.Add(GoalLadderModel.KindTitles["breed_extra"]);
            all.Add("ひとりでも：" + GoalLadderModel.KindTitles["breed_extra"]);
            all.Add("卒業：10連スカウト券×1");
            all.Add("配合素材を1個使って、もう1回（残り 6個）");
            all.Add("疲れ 55 → 25（残り 1個）");
            all = all.Where(x => !string.IsNullOrEmpty(x)).Distinct().ToList();
            var text = string.Join("", all);
            check(!text.Contains("今だけ") && !text.Contains("残りわずか") && !text.Contains("お得") && !text.Contains("倍") && !text.Contains("ショップ") && !text.Contains("購入"), "week 2: no urgency words, no shop or purchase");
            Loc.LoadEnglish(File.ReadAllText(Path.Combine(root, "engine", "Muchi.Client", "Resources", "Muchi", "server-en.json")));
            Loc.LoadEnglish(File.ReadAllText(Path.Combine(root, "engine", "Muchi.Client", "Resources", "Muchi", "ui-en.json")));
            Loc.SetLocale("en");
            try
            {
                var miss = all.Where(x => Loc.HasJapanese(Loc.T(x))).ToList();
                check(miss.Count == 0, "week 2: every line has English (" + all.Count + " lines" + (miss.Count > 0 ? "; missing: " + string.Join(" | ", miss) : "; e.g. " + Loc.T(m7.TomorrowLine) + " / " + Loc.T(arc7.Main)) + ")");
            }
            finally { Loc.SetLocale("ja"); }
        }
        finally { GameDay.Use(prevRule); }
    }
}
